{
  "name": "INHECO孵育振荡器堆叠系统",
  "name_en": "INHECO Incubator/Shaker Stack",
  "manufacturer": "INHECO",
  "description": "由多个可堆叠孵育振荡单元组成的实验室自动化设备，带有装载托盘，可对样品或微孔板进行温度控制孵育与振荡混匀，常用于自动化培养、反应孵育和样品处理流程。",
  "description_en": "A laboratory automation device composed of multiple stackable incubator/shaker units with loading trays, used to provide temperature-controlled incubation and shaking for samples or microplates in automated culture, reaction incubation, and sample-processing workflows.",
  "tag_hints": [
    "incubator shaker",
    "temperature-controlled incubation",
    "automated plate handling",
    "stacked lab modules",
    "sample shaking",
    "microplate incubation"
  ],
  "actions": [
    {
      "action_name": "auto-num_units",
      "description": "获取堆叠中已连接单元的数量。",
      "description_en": "Get the number of connected units in the stack."
    },
    {
      "action_name": "auto-request_loading_tray_states",
      "description": "查询所有单元的装载托盘状态。",
      "description_en": "Request the loading tray states of all units."
    },
    {
      "action_name": "auto-request_temperature_control_states",
      "description": "查询所有单元的温度控制状态。",
      "description_en": "Request the temperature-control states of all units."
    },
    {
      "action_name": "auto-request_shaking_states",
      "description": "查询所有单元的振荡状态。",
      "description_en": "Request the shaking states of all units."
    },
    {
      "action_name": "auto-open_all",
      "description": "打开堆叠中的所有单元。",
      "description_en": "Open all units in the stack."
    },
    {
      "action_name": "auto-close_all",
      "description": "关闭堆叠中的所有单元。",
      "description_en": "Close all units in the stack."
    },
    {
      "action_name": "auto-start_all_temperature_control",
      "description": "启动所有单元的温度控制并设定目标温度。",
      "description_en": "Start temperature control for all units and set the target temperature."
    },
    {
      "action_name": "auto-get_all_temperatures",
      "description": "获取所有单元的当前温度。",
      "description_en": "Get the current temperatures of all units."
    },
    {
      "action_name": "auto-stop_all_temperature_control",
      "description": "停止所有单元的温度控制。",
      "description_en": "Stop temperature control for all units."
    },
    {
      "action_name": "auto-shake",
      "description": "启动所有单元的振荡。",
      "description_en": "Start shaking for all units."
    },
    {
      "action_name": "auto-stop_all_shaking",
      "description": "停止所有单元的振荡。",
      "description_en": "Stop shaking for all units."
    }
  ]
}

